84:     async isValidSlpTxid(txid: string) {
85:         if(txid && !this.cachedValidations[txid]) {
86:             this.cachedValidations[txid] = { hex: null, validity: null, parents: [], details: null, invalidReason: null }
87:             this.cachedValidations[txid].hex = await this.getRawTransaction(txid);
88:         }
89: 
90:         // Check to see how we should proceed based on the validation-cache state
91:         if(!this.cachedValidations[txid].hex)
92:             await this.waitForTransactionPreProcessing(txid);
93:         if(typeof this.cachedValidations[txid].validity === 'boolean')
94:             return this.cachedValidations[txid].validity;
95:         if(this.cachedValidations[txid].details)
96:             await this.waitForParentValidationProcessing(txid);
97: 
98:         // Check SLP message validity
99:         let txn: BitcoreTransaction = new bitcore.Transaction(this.cachedValidations[txid].hex)
100:         let slpmsg: SlpTransactionDetails;
101:         try {
102:             slpmsg = this.cachedValidations[txid].details = this.slp.parseSlpOutputScript(txn.outputs[0]._scriptBuffer)
103:         } catch(e) {
104:             this.cachedValidations[txid].invalidReason = "SLP OP_RETURN parsing error (" + e.message + ")."
105:             return this.cachedValidations[txid].validity = false;
106:         }
107: 
108:         // Check DAG validity
109:         if(slpmsg.transactionType === SlpTransactionType.GENESIS) {
110:             return this.cachedValidations[txid].validity = true;
111:         } 
112:         else if (slpmsg.transactionType === SlpTransactionType.MINT) {
113:             for(let i = 0; i < txn.inputs.length; i++) {
