146:                         if(input_slpmsg.transactionType === SlpTransactionType.GENESIS)
147:                             input_slpmsg.tokenIdHex = input_txid;
148:                         if(input_slpmsg.tokenIdHex === slpmsg.tokenIdHex) {
149:                             if(input_slpmsg.transactionType === SlpTransactionType.SEND) {
150:                                 tokenInQty = tokenInQty.plus(input_slpmsg.sendOutputs[txn.inputs[i].outputIndex])
151:                                 this.cachedValidations[txid].parents.push({txid: txn.inputs[i].prevTxId.toString('hex'), versionType: input_slpmsg.versionType, valid: null, inputQty: input_slpmsg.sendOutputs[txn.inputs[i].outputIndex] })
152:                             }
153:                             else if(input_slpmsg.transactionType === SlpTransactionType.GENESIS || input_slpmsg.transactionType === SlpTransactionType.MINT) {
154:                                 if(txn.inputs[i].outputIndex === 1)
155:                                     tokenInQty = tokenInQty.plus(input_slpmsg.genesisOrMintQuantity)
156:                                     this.cachedValidations[txid].parents.push({txid: txn.inputs[i].prevTxId.toString('hex'), versionType: input_slpmsg.versionType, valid: null, inputQty: input_slpmsg.genesisOrMintQuantity })
157:                             }
158:                         }
159:                     } catch(_) {}
160:                 }
161:             }
162:             
163:             // Check token inputs are greater than token outputs (includes valid and invalid inputs)
164:             if(tokenOutQty.isGreaterThan(tokenInQty)) {
165:                 this.cachedValidations[txid].invalidReason = "Token outputs are greater than possible token inputs."
166:                 return this.cachedValidations[txid].validity = false;
167:             }
168:         }
169: 
170:         // Set validity validation-cache for parents, and handle MINT condition with no valid input
171:         for(let i = 0; i < this.cachedValidations[txid].parents.length; i++) {
172:             let valid = await this.isValidSlpTxid(this.cachedValidations[txid].parents[i].txid)
173:             this.cachedValidations[txid].parents.find(p => p.txid === this.cachedValidations[txid].parents[i].txid).valid = valid;
174:             if(this.cachedValidations[txid].details.transactionType === SlpTransactionType.MINT && !valid) {
175:                 this.cachedValidations[txid].invalidReason = "MINT transaction with invalid baton parent."
176:                 return this.cachedValidations[txid].validity = false;
177:             }
178:         }
