180:         // Check valid inputs are greater than token outputs
181:         if(this.cachedValidations[txid].details.transactionType === SlpTransactionType.SEND) {
182:             let validInputQty = this.cachedValidations[txid].parents.reduce((t, v) => { return v.valid ? t.plus(v.inputQty) : t }, new BigNumber(0));
183:             let tokenOutQty = slpmsg.sendOutputs.reduce((t,v)=>{ return t.plus(v) }, new BigNumber(0))
184:             if(tokenOutQty.isGreaterThan(validInputQty)) {
185:                 this.cachedValidations[txid].invalidReason = "Token outputs are greater than valid token inputs."
186:                 return this.cachedValidations[txid].validity = false;
187:             }
188:         }
